import numpy as np

pat_small = np.array([[6, 2, 2],
                      [2, 2, 2],
                      [2, 2, 6]])

height, width = 21, 21
grid = np.zeros((height, width), dtype=int)
tile_y, tile_x = 3, 3

for y in range(tile_y):
    for x in range(tile_x):
        val = pat_small[y, x]
        for ty in range(height):
            for tx in range(width):
                if (ty // 3 == y and tx // 3 == x):
                    grid[ty, tx] = val

print("Top section:")
for row in range(5):
    print(f"Row {row}: {list(grid[row])}")
print("Bottom section:")
for row in range(17, 21):
    print(f"Row {row}: {list(grid[row])}")
